<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useFitness, tone, asset } from './store'
import { clone, newDay, addDays, cycleDays, cycleOn, dayOn, type TrainingDay, type TrainingTemplate } from '../../../shared/fitness'
import { localDate } from '../../../shared/date'
import ItemEditor from './ItemEditor.vue'
import { confirmDelete } from '../lib/api'
const props=defineProps<{ page: string }>(), emit=defineEmits<{navigate:[page:string]}>(), fs=useFitness()
const today=localDate(), cycle=ref(Math.max(0,cycleOn(fs.data,today))), selected=ref(0), editCycle=ref(cycle.value), scope=ref('one'), draft=ref<TrainingDay>(newDay()), editing=ref(false), drag=ref(-1), templateId=ref(fs.data.templates[0]?.id || ''), search=ref(''), templateFilter=ref('全部')
const days=computed(()=>cycleDays(fs.data,cycle.value)), current=computed(()=>dayOn(fs.data,today)), templates=computed(()=>fs.data.templates.filter(t=>(templateFilter.value==='全部'||t.type===templateFilter.value||t.items.some(i=>fs.exercise(i.exerciseId)?.tags.includes(templateFilter.value)))&&t.title.includes(search.value))), template=computed(()=>fs.data.templates.find(t=>t.id===templateId.value)), editingTemplate=ref(false)
const dateOf=(c:number,i=0)=>addDays(fs.data.startDate,c*fs.data.rhythm.length+i), dateText=(d:string)=>d.slice(5).replace('-','.')
const range=(c:number)=>dateText(dateOf(c))+' — '+dateText(dateOf(c,fs.data.rhythm.length-1))
watch(()=>props.page,()=>{editing.value=false})
function pick(c:number,i:number):void {editCycle.value=c;selected.value=i;draft.value=clone(cycleDays(fs.data,c)[i]);editing.value=true}
function applyTemplate():void {const t=fs.data.templates.find(t=>t.id===draft.value.templateId);if(t)draft.value={...clone(t),templateId:t.id}}
async function apply():Promise<void>{
 if(draft.value.type==='休息')draft.value.items=[]
 if(scope.value==='future'){for(let c=0;c<editCycle.value;c++)if(!fs.data.overrides[c])fs.data.overrides[c]=clone(fs.data.rhythm);fs.data.rhythm[selected.value]=clone(draft.value);for(const [c,d] of Object.entries(fs.data.overrides))if(Number(c)>=editCycle.value)d[selected.value]=clone(draft.value)}
 else{fs.data.overrides[editCycle.value]=clone(cycleDays(fs.data,editCycle.value));fs.data.overrides[editCycle.value][selected.value]=clone(draft.value)}
 await fs.save('训练日已保存');editing.value=false
}
function addTemplate():void {const t:TrainingTemplate={...newDay('新训练模板'),id:crypto.randomUUID()};fs.data.templates.push(t);templateId.value=t.id;editingTemplate.value=true}
function copyTemplate():void {if(!template.value)return;const t=clone(template.value);t.id=crypto.randomUUID();t.title+=' · 副本';fs.data.templates.push(t);templateId.value=t.id;void fs.save('模板已复制')}
async function deleteTemplate():Promise<void>{if(template.value&&await confirmDelete(template.value.title)){fs.data.templates=fs.data.templates.filter(t=>t.id!==templateId.value);templateId.value=fs.data.templates[0]?.id||'';await fs.save()}}
function templateToDay():void{if(!template.value)return;draft.value={...clone(template.value),templateId:template.value.id};editing.value=true}
function reorder(i:number):void{const [d]=fs.data.rhythm.splice(drag.value,1);fs.data.rhythm.splice(i,0,d);fs.data.overrides={}}
async function removeRhythm(i:number):Promise<void>{if(fs.data.rhythm.length===1)return;if(await confirmDelete('这一天（会重新生成周期安排）')){fs.data.rhythm.splice(i,1);fs.data.overrides={};await fs.save()}}
const templateTarget=ref(0)
async function useTemplate():Promise<void>{editCycle.value=cycle.value;selected.value=templateTarget.value;templateToDay();await apply()}
const typeOptions=['推','拉','腿','有氧','自定义','休息']
</script>
<template>
 <div class="fit-plan-pane" :class="{'editing-cycle':page==='cycles'&&editing}">
 <template v-if="page==='overview'">
  <section class="fit-hero fit-card"><div><small>我的训练节奏</small><h2>{{ fs.data.rhythm.filter(d=>d.type!=='休息').length }} 天训练，{{ fs.data.rhythm.filter(d=>d.type==='休息').length }} 天恢复。</h2><p>以 {{ fs.data.rhythm.length }} 天为一个周期，不受星期限制。</p></div><div class="fit-hero-rhythm"><span>{{ fs.data.rhythm.filter(d=>d.type!=='休息').length }} 天训练</span><span>{{ fs.data.rhythm.filter(d=>d.type==='休息').length }} 天休息</span><button class="fit-button" @click="emit('navigate','cycles')">调整节奏</button></div><img class="fit-hero-art" :src="asset('fitness/hero.png')" alt="正在伸展的薄荷绿运动伙伴"/></section>
  <div class="fit-columns"><div class="fit-main-column"><section class="fit-card"><header><h2>▦ 本轮安排</h2><div class="fit-cycle-nav"><button @click="cycle=Math.max(0,cycle-1)">‹</button><strong>第 {{ cycle+1 }} 轮 · {{ range(cycle) }}</strong><button @click="cycle++">›</button></div></header><div class="fit-day-grid" :style="{'--day-count':Math.min(days.length,4)}"><button v-for="(d,i) in days" :key="i" class="fit-day" :class="[tone(d.type),{today:dateOf(cycle,i)===today}]" @click="pick(cycle,i)"><strong>{{ dateText(dateOf(cycle,i)) }} <small v-if="dateOf(cycle,i)===today">今天</small></strong><small>第 {{ i+1 }} 天</small><div class="fit-equipment" :class="tone(d.type)"><span v-if="d.type==='休息'">☾</span><img v-else-if="d.type==='腿'" :src="asset('fitness/kettlebell.png')" alt="壶铃示意图"/><i v-else></i></div><b>{{ d.title }}</b><span class="fit-day-foot">{{ d.type==='休息'?'放松一下':'计划 '+d.items.length+' 个动作' }} ›</span></button></div><button class="fit-next-cycle" @click="cycle++;emit('navigate','cycles')">⟳ 下一轮 {{ range(cycle+1) }} <span class="fit-badge">{{ fs.data.overrides[cycle+1]?'已单独调整':'复用基础模板' }}</span><span>查看安排 →</span></button></section>
  <section class="fit-card"><header><div><h2>♧ 今日计划 · {{ current?.title||'尚未开始' }}</h2><p class="fit-muted">{{ current?.items.length||0 }} 个动作 · 按计划安排</p></div><button class="fit-button" v-if="current" @click="pick(Math.max(0,cycleOn(fs.data,today)),Math.max(0,Math.round((Date.parse(today)-Date.parse(fs.data.startDate))/86400000))%fs.data.rhythm.length)">✎ 编辑当日</button></header><table class="fit-table"><thead><tr><th>动作</th><th>目标组数 × 次数</th><th>参考重量</th><th>组间休息</th></tr></thead><tbody><tr v-for="item in current?.items" :key="item.exerciseId"><td class="fit-name-cell"><img v-if="fs.exercise(item.exerciseId)?.image" :src="asset(fs.exercise(item.exerciseId).image)"/>{{ fs.exercise(item.exerciseId)?.name }}</td><td>{{ item.sets.length }} × {{ item.sets[0]?.reps??'—' }}</td><td>{{ item.sets[0]?.weight??'—' }} kg</td><td>{{ item.rest }} 秒</td></tr></tbody></table><p v-if="!current?.items.length" class="fit-empty">{{ current?.type==='休息'?'今天是恢复日，给身体一点休息时间。':'还没有安排动作，点击编辑添加。' }}</p><p class="fit-muted fit-footnote">这里展示计划，不代表实际训练记录。</p><p v-if="current?.notes" class="fit-note">{{ current.notes }}</p></section></div>
  <aside class="fit-side-column"><section class="fit-card"><header><div><h2>▱ 我的训练模板</h2><p class="fit-muted">保存常用训练，换一轮也能直接用。</p></div><button class="fit-text" @click="emit('navigate','templates')">管理 →</button></header><button class="fit-template-tile" v-for="t in fs.data.templates.slice(0,4)" :key="t.id" @click="templateId=t.id;emit('navigate','templates')"><div class="fit-equipment" :class="tone(t.type)"><i/></div><span><strong>{{ t.title }}</strong><small>{{ t.items.length }} 个动作</small></span><b>›</b></button><button class="fit-wide-button" @click="addTemplate();emit('navigate','templates')">＋ 创建模板</button></section><section class="fit-card"><h2>⟳ 周期方式</h2><div class="fit-segment"><button v-for="m in ['默认重复','逐轮自定']" :class="{active:fs.data.mode===m}" @click="fs.data.mode=m;fs.save()">{{ m }}</button></div><p class="fit-muted">新周期复用模板，也能单独修改任一轮。</p><button class="fit-text" @click="emit('navigate','cycles')">调整后续周期 →</button></section><section class="fit-card"><h2>▥ 过往训练</h2><p class="fit-history-number">{{ fs.data.records.length }} <small>次训练记录</small></p><button class="fit-text" @click="emit('navigate','calendar')">查看记录 →</button></section></aside></div>
 </template>
 <template v-if="page==='cycles'">
  <section class="fit-card fit-rhythm-settings"><div class="fit-form-grid"><label>计划名称<input v-model="fs.data.name"/></label><label>起始日期<input v-model="fs.data.startDate" type="date"/></label><label>循环方式<select v-model="fs.data.mode"><option>默认重复</option><option>逐轮自定</option></select></label><button class="fit-primary" @click="fs.save('安排已保存')">保存安排</button></div><div class="fit-rhythm"><strong>基础节奏</strong><div v-for="(d,i) in fs.data.rhythm" :key="i" :class="tone(d.type)" draggable="true" @dragstart="drag=i" @dragover.prevent @drop.prevent="reorder(i)"><b>{{ i+1 }}</b><select v-model="d.type" @change="d.title=d.type==='休息'?'休息与恢复':d.type+' · 自定义训练';fs.data.overrides={}"><option v-for="t in typeOptions">{{ t }}</option></select><button @click="removeRhythm(i)" aria-label="删除周期日">×</button></div><button class="fit-button" @click="fs.data.rhythm.push(newDay());fs.data.overrides={}">＋ 添加一天</button><small>{{ fs.data.rhythm.length }} 天一轮 · 可拖动调整顺序</small></div></section>
  <div class="fit-columns"><section class="fit-card"><header><h2>▦ 按轮查看</h2><div class="fit-cycle-nav"><button @click="cycle=Math.max(0,cycle-1)">‹</button><strong>第 {{ cycle+1 }} 轮起</strong><button @click="cycle++">›</button></div></header><div v-for="c in [cycle,cycle+1,cycle+2]" :key="c" class="fit-cycle-row"><header><h3>第 {{ c+1 }} 轮 <small>{{ range(c) }}</small></h3><span class="fit-badge">{{ fs.data.overrides[c]?'已单独调整':'使用基础模板' }}</span><button class="fit-text" @click="fs.data.overrides[c+1]=clone(cycleDays(fs.data,c));fs.save('已复制到下一轮')">复制到下一轮</button><button v-if="fs.data.overrides[c]" class="fit-text" @click="delete fs.data.overrides[c];fs.save('已恢复模板')">恢复模板</button></header><div class="fit-day-grid" :style="{'--day-count':Math.min(fs.data.rhythm.length,4)}"><button v-for="(d,i) in cycleDays(fs.data,c)" :key="i" class="fit-day compact" :class="[tone(d.type),{today:editing&&editCycle===c&&selected===i}]" @click="pick(c,i)"><strong>{{ dateText(dateOf(c,i)) }}</strong><small>第 {{ i+1 }} 天</small><b>{{ d.title }}</b><span>计划 {{ d.items.length }} 个动作</span></button></div></div><div class="fit-actions"><button class="fit-button" @click="fs.data.startDate=addDays(fs.data.startDate,1);fs.save('计划整体顺延一天')">整体顺延一天</button><button class="fit-button" @click="pick(cycle,0);draft=newDay('休息与恢复','休息')">设为休息日</button><small class="fit-muted">调整计划不会修改已有训练记录。</small></div></section><aside class="fit-card fit-inspector" v-if="!editing"><h2>✎ 编辑训练日</h2><p class="fit-empty">点击左侧任一训练日，引用模板或单独编排。</p><p class="fit-muted">默认重复：以基础模板循环；逐轮自定：每轮可以另选不同训练。</p></aside></div>
 </template>
 <template v-if="page==='templates'">
  <div class="fit-template-workspace"><aside class="fit-card"><h2>模板列表</h2><input v-model="search" placeholder="搜索模板"/><div class="fit-filter-chips"><button v-for="t in ['全部','力量','有氧','自定义']" :class="{active:templateFilter===t}" @click="templateFilter=t">{{ t }}</button></div><button v-for="t in templates" class="fit-template-library-tile" :class="[tone(t.type),{selected:templateId===t.id}]" @click="templateId=t.id"><div><strong>{{ t.title }}</strong><p>{{ t.items.length }} 个动作</p><small>{{ t.type }}</small></div><div class="fit-equipment" :class="tone(t.type)"><i/></div></button><button class="fit-wide-button" @click="addTemplate">＋ 创建空白模板</button></aside><section class="fit-card" v-if="template"><header><div><h2>{{ template.title }}</h2><p class="fit-muted">模板内容 · 保存后可应用到指定训练日</p></div><button class="fit-button" @click="copyTemplate">复制模板</button><button class="fit-primary" @click="fs.save('模板已保存')">保存模板</button><button class="fit-icon" aria-label="删除模板" @click="deleteTemplate">×</button></header><div class="fit-form-grid"><label>模板名称<input v-model="template.title"/></label><label>训练类型<select v-model="template.type"><option v-for="t in typeOptions.filter(t=>t!=='休息')">{{ t }}</option></select></label></div><ItemEditor :items="template.items"/><label class="fit-label">训练备注<textarea v-model="template.notes" placeholder="个人训练备注（可选）"/></label><div class="fit-apply-panel"><h3>应用模板到计划</h3><div class="fit-form-grid"><label>周期<input :value="cycle+1" type="number" min="1" aria-label="周期编号" @change="cycle=Number(($event.target as HTMLInputElement).value)-1"/></label><label>训练日<select v-model="templateTarget"><option v-for="(d,i) in days" :value="i">第{{ i+1 }}天 · {{ d.title }}</option></select></label><label>应用范围<select v-model="scope"><option value="one">仅所选训练日</option><option value="future">本轮及后续同一天</option></select></label><button class="fit-primary" @click="useTemplate">确认应用</button></div></div><p class="fit-muted">修改模板不会自动覆盖已安排的训练日。</p></section><section class="fit-card fit-empty" v-else>创建一份模板，保存自己的常用训练组合。</section></div>
 </template>
 <section v-if="editing" class="fit-card fit-day-edit"><header><h2>✎ 编辑训练日 · 第 {{ editCycle+1 }} 轮 / 第 {{ selected+1 }} 天</h2><button class="fit-icon" @click="editing=false">×</button></header><div class="fit-form-grid"><label>名称<input v-model="draft.title"/></label><label>类型<select v-model="draft.type"><option v-for="t in typeOptions">{{ t }}</option></select></label><label>引用模板<select v-model="draft.templateId" @change="applyTemplate"><option value="">单独编排</option><option v-for="t in fs.data.templates" :value="t.id">{{ t.title }}</option></select></label></div><ItemEditor v-if="draft.type!=='休息'" :items="draft.items"/><label class="fit-label">备注<textarea v-model="draft.notes"/></label><footer class="fit-actions"><select v-model="scope"><option value="one">仅本轮</option><option value="future">本轮及后续</option></select><button class="fit-primary" @click="apply">应用修改</button><small class="fit-muted">已有训练记录保持原样。</small></footer></section>
 </div>
</template>
